package com.gzy.qinglian;
import android.app.Activity;
import android.content.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import com.google.android.material.button.MaterialButton;
import com.google.android.material.dialog.MaterialAlertDialogBuilder;
import java.util.concurrent.*;
import java.util.function.Consumer;
import org.json.*;
/** Explicit account activation; device identifiers are binding data, never authentication. */
final class AccountPage {
 final Activity activity;final Consumer<JSONObject> save;final Handler main=new Handler(Looper.getMainLooper());final ExecutorService worker=Executors.newSingleThreadExecutor();
 final LinearLayout box,list,login,account,exports;final ScrollView content;final TextView status;final EditText token,password,size,remark;final Spinner protocol;final MaterialButton activate,register,create,refresh;boolean busy,closed;
 final String[] protocols={"vmess","vless","trojan","shadowsocks","hysteria2"};
 AccountPage(Activity a,Consumer<JSONObject> save){
  activity=a;this.save=save;box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);int pad=(int)(20*a.getResources().getDisplayMetrics().density);box.setPadding(pad,pad,pad,pad);
  TextView guest=new TextView(a);guest.setText("免登录即可在连接页使用VPN，每次手动连接最多64GB；自动恢复沿用本次额度。登录账号后可查看累计流量并导出独立节点。");box.addView(guest);
  login=section("注册与登录");account=section("账号概览");exports=section("独立节点导出");TextView exportNote=new TextView(a);exportNote.setText("每周256GB可分配额度，创建后7天有效，撤销不返还。TLS协议请使用随包CA并保留证书校验。");exports.addView(exportNote);
  TextView note=new TextView(a);note.setText("每周可分配256GB，节点创建后7天有效。按UTC周一重置，撤销不返还本周已分配额度。同一设备只能注册一个账号，账号支持多设备登录。设备绑定使用本应用范围Android ID摘要，不读取IMEI。登录前须同意永久保存主连接与导出节点连接域名与时间。");login.addView(note);
  token=new EditText(a);token.setSingleLine(true);token.setHint("用户名（3..32字符）");token.setText(a.getSharedPreferences("export-api",0).getString("username",""));login.addView(token);
  password=new EditText(a);password.setSingleLine(true);password.setHint("密码（8..72字节）");password.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);login.addView(password);
  activate=button("登录账号");login.addView(activate);register=button("注册账号（每设备限一个）");login.addView(register);status=new TextView(a);account.addView(status);
  MaterialButton logout=button("退出此设备账号");account.addView(logout);logout.setOnClickListener(v->logout());
  protocol=new Spinner(a);protocol.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"VMess","VLESS","Trojan","Shadowsocks","Hysteria2"}));exports.addView(protocol);
  size=new EditText(a);size.setHint("导出大小：1..256 GB");size.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);size.setText("16");exports.addView(size);
  remark=new EditText(a);remark.setSingleLine(true);remark.setHint("备注名称（可选）");remark.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(64)});exports.addView(remark);
  create=button("创建独立节点");exports.addView(create);refresh=button("刷新额度 / 节点");account.addView(refresh);MaterialButton history=button("查看我的域名记录（永久保存）");account.addView(history);history.setOnClickListener(v->history());list=new LinearLayout(a);list.setOrientation(LinearLayout.VERTICAL);exports.addView(list);
  content=new ScrollView(a);content.setFillViewport(true);content.addView(box);renderMode();
  activate.setOnClickListener(v->account(false));register.setOnClickListener(v->account(true));
  refresh.setOnClickListener(v->run(this::snapshot));create.setOnClickListener(v->{int gb;try{gb=Integer.parseInt(size.getText().toString());if(gb<1||gb>256)throw new Exception();}catch(Exception invalid){size.setError("请输入1..256之间的整数");return;}String p=protocols[protocol.getSelectedItemPosition()],label=remark.getText().toString().trim();
   new MaterialAlertDialogBuilder(a).setTitle("确认导出").setMessage("分配"+gb+"GB，创建后7天过期，本周额度立即扣减。撤销不会返还额度。").setPositiveButton("创建",(d,w)->run(()->{ExportClient.create(a,p,gb*1024,label);Thread.sleep(800);return snapshot();})).setNegativeButton("取消",null).show();});
 }
 void account(boolean signup){if(!TunnelService.state.equals("disconnected")&&!TunnelService.state.equals("error")){Toast.makeText(activity,"请先断开VPN，再登录或注册账号",Toast.LENGTH_LONG).show();return;}String name=token.getText().toString().trim(),pass=password.getText().toString();if(name.length()<3||name.length()>32||pass.getBytes(java.nio.charset.StandardCharsets.UTF_8).length<8||pass.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>72){status.setText("用户名3..32字符，密码8..72字节");return;}
  new MaterialAlertDialogBuilder(activity).setTitle("账号与永久域名记录告知").setMessage("注册/登录后，服务器将永久保存该账号主连接与导出节点访问的域名和时间，管理员及你本人可查看；包含应用后台请求，不等同于浏览器页面历史，不包含HTTPS完整路径、查询参数或页面内容。提交应用范围Android ID摘要用于同设备限制；同一账号可多设备登录，额度统一计算。撤销节点后停止新记录，已有记录不会自动清理。不同意请取消。").setPositiveButton("同意并"+(signup?"注册":"登录"),(d,w)->run(()->{if(!TunnelService.state.equals("disconnected")&&!TunnelService.state.equals("error"))throw new Exception("disconnect first");JSONObject result=ExportClient.request(activity,signup?"register":"login",new JSONObject().put("username",name).put("password",pass).put("historyConsent","domains-permanent-v1"),"0".repeat(64));if(!activity.getSharedPreferences("export-api",0).edit().putString("token",result.getString("token")).putString("username",result.getString("username")).commit())throw new Exception();return snapshot();},true)).setNegativeButton("取消",null).show();
 }
 MaterialButton button(String title){MaterialButton b=new MaterialButton(activity);b.setText(title);return b;}
 JSONObject snapshot()throws Exception{return new JSONObject().put("quota",ExportClient.request(activity,"quota",null,ExportClient.token(activity))).put("nodes",ExportClient.request(activity,"nodes",null,ExportClient.token(activity)).getJSONArray("nodes"));}
 interface Job{JSONObject get()throws Exception;}
 void run(Job job){run(job,false);}
 void run(Job job,boolean accountAction){if(busy||closed)return;busy=true;activate.setEnabled(false);register.setEnabled(false);create.setEnabled(false);refresh.setEnabled(false);status.setText("正在同步…");worker.execute(()->{JSONObject result=null;String error=null;try{result=job.get();}catch(ApiEndpoint.HttpFailure fail){error=fail.code==401?"账号密码错误、已撤销或登录已过期":fail.code==403?"凭据已绑定其他设备，请联系管理员":fail.code==409?(accountAction?"同一设备已注册或用户名不可用，请登录已有账号":"本周额度或有效节点数量已达上限，请刷新查看"):"API服务暂不可用";}catch(Exception fail){error="请求未完成，请刷新查看或重试。同一请求重试不会重复扣额。切换账号前请先断开VPN。";}JSONObject value=result;String message=error;main.post(()->{if(closed||activity.isDestroyed())return;busy=false;activate.setEnabled(true);register.setEnabled(true);create.setEnabled(true);refresh.setEnabled(true);renderMode();if(message!=null){status.setText(message);return;}render(value);});});}
 void render(JSONObject data){renderMode();password.setText("");try{
  JSONObject q=data.getJSONObject("quota");status.setText("当前账号："+activity.getSharedPreferences("export-api",0).getString("username","")+"\n账号累计用量（主连接＋导出）："+TunnelService.size(q.getLong("cumulativeTotalBytes"))+"\n上传："+TunnelService.size(q.getLong("cumulativeUploadBytes"))+" · 下载："+TunnelService.size(q.getLong("cumulativeDownloadBytes"))+"\n本周剩余额度："+String.format(java.util.Locale.CHINA,"%.1f GB",q.getLong("remainingBytes")/1073741824.0)+"\n重置："+new java.text.SimpleDateFormat("MM-dd HH:mm",java.util.Locale.CHINA).format(new java.util.Date(q.getLong("resetsAt")*1000))+"\n含主连接最多同时8条节点；全部用户合计最多16条。");list.removeAllViews();JSONArray nodes=data.getJSONArray("nodes");
  for(int i=0;i<nodes.length();i++){JSONObject n=nodes.getJSONObject(i);String id=n.getString("id"),state=n.getString("status");String label=n.optString("remark","")+" · "+n.getString("protocol").toUpperCase(java.util.Locale.ROOT)+" · "+String.format(java.util.Locale.CHINA,"%.1f GB",n.getLong("totalBytes")/1073741824.0)+" · "+state;MaterialButton row=button(label);list.addView(row);row.setOnClickListener(v->{
    if(!n.has("profile")){new MaterialAlertDialogBuilder(activity).setTitle("节点状态").setMessage("当前："+state+"。新节点通常几秒内可用，请刷新；异常请联系管理员。").setPositiveButton("刷新",(d,w)->run(this::snapshot)).setNeutralButton("撤销",(d,w)->revoke(id)).setNegativeButton("关闭",null).show();return;}
    JSONObject profile=n.optJSONObject("profile");new MaterialAlertDialogBuilder(activity).setTitle("导出独立节点").setMessage("TLS协议请使用压缩包内的公开CA及配置，保持证书验证开启。仅导出自己的节点，妥善保管凭据。").setPositiveButton("保存配置包",(d,w)->save.accept(profile)).setNeutralButton("复制链接",(d,w)->{((android.content.ClipboardManager)activity.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("节点",profile.optString("uri")));Toast.makeText(activity,"已复制；TLS客户端需配置附带CA",Toast.LENGTH_LONG).show();}).setNegativeButton("撤销节点",(d,w)->revoke(id)).show();
   });}
 }catch(Exception invalid){status.setText("服务端响应无效，请联系管理员");}}
 void revoke(String id){new MaterialAlertDialogBuilder(activity).setTitle("撤销节点？").setMessage("会停止该导出节点，不返还本周额度。").setPositiveButton("撤销",(d,w)->run(()->{ExportClient.request(activity,"nodes/"+id+"/revoke",new JSONObject(),ExportClient.token(activity));return snapshot();})).setNegativeButton("取消",null).show();}

 void history(){if(busy||closed)return;worker.execute(()->{String text;try{JSONArray entries=ExportClient.request(activity,"history",null,ExportClient.token(activity)).getJSONArray("records");StringBuilder b=new StringBuilder("最近200条连接域名记录，含应用后台请求。服务器永久保存。");b.append((char)10).append((char)10);for(int i=0;i<entries.length();i++){JSONObject e=entries.getJSONObject(i);b.append(new java.text.SimpleDateFormat("MM-dd HH:mm",java.util.Locale.CHINA).format(new java.util.Date(e.getLong("lastSeen")*1000))).append(" · ").append(e.getString("domain")).append((char)10);}text=b.toString();}catch(Exception e){text="记录暂不可用，请确认账号已登录";}String value=text;main.post(()->{if(!closed&&!activity.isDestroyed())new MaterialAlertDialogBuilder(activity).setTitle("我的域名记录").setMessage(value).setPositiveButton("关闭",null).show();});});}
 LinearLayout section(String title){com.google.android.material.card.MaterialCardView card=new com.google.android.material.card.MaterialCardView(activity);card.setRadius(16*activity.getResources().getDisplayMetrics().density);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=(int)(16*activity.getResources().getDisplayMetrics().density);box.addView(card,lp);LinearLayout inner=new LinearLayout(activity);inner.setOrientation(LinearLayout.VERTICAL);int pad=(int)(16*activity.getResources().getDisplayMetrics().density);inner.setPadding(pad,pad,pad,pad);card.addView(inner);TextView heading=new TextView(activity);heading.setText(title);heading.setTextSize(20);heading.setTypeface(null,android.graphics.Typeface.BOLD);inner.addView(heading);return inner;}
 void renderMode(){boolean signed=!ExportClient.token(activity).isEmpty();LinearLayout target=signed?account:login;if(status.getParent()!=target){((android.view.ViewGroup)status.getParent()).removeView(status);target.addView(status,signed?1:target.getChildCount());}((View)login.getParent()).setVisibility(signed?View.GONE:View.VISIBLE);((View)account.getParent()).setVisibility(signed?View.VISIBLE:View.GONE);((View)exports.getParent()).setVisibility(signed?View.VISIBLE:View.GONE);}
 void logout(){if(busy||closed)return;if(!TunnelService.state.equals("disconnected")&&!TunnelService.state.equals("error")){Toast.makeText(activity,"请先断开VPN再退出账号",Toast.LENGTH_LONG).show();return;}busy=true;worker.execute(()->{try{ExportClient.request(activity,"logout",new JSONObject(),ExportClient.token(activity));}catch(Exception ignored){}activity.getSharedPreferences("export-api",0).edit().remove("token").remove("username").remove("pending").commit();ProfileMonitor.current=null;main.post(()->{if(closed)return;busy=false;password.setText("");status.setText("未登录，可返回连接页直接使用访客VPN");list.removeAllViews();renderMode();});});}
 void close(){closed=true;worker.shutdownNow();main.removeCallbacksAndMessages(null);}
 void show(){if(!ExportClient.token(activity).isEmpty())run(this::snapshot);}

}
